using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // ───────────────────────────────────────────────
    // AddItem
    // ───────────────────────────────────────────────

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("HappyPath")]
    public void AddItem_ValidSkuQuantityPrice_ThrowsNotImplementedException()
    {
        // Arrange
        var sku = "SKU-001";
        var quantity = 2;
        var price = 9.99m;

        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem(sku, quantity, price));
    }

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("HappyPath")]
    [DataRow("SKU-A", 1, 0.01, DisplayName = "Minimum positive price")]
    [DataRow("SKU-B", 100, 999.99, DisplayName = "Large quantity and price")]
    [DataRow("SKU-C", 1, 0.00, DisplayName = "Zero price (free item)")]
    public void AddItem_VariousValidInputs_ThrowsNotImplementedException(
        string sku, int quantity, double priceDouble)
    {
        // Arrange
        var price = (decimal)priceDouble;

        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem(sku, quantity, price));
    }

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("EdgeCase")]
    public void AddItem_ZeroQuantity_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem("SKU-ZERO", 0, 5.00m));
    }

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("EdgeCase")]
    public void AddItem_NegativeQuantity_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem("SKU-NEG", -1, 5.00m));
    }

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("EdgeCase")]
    public void AddItem_NegativePrice_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem("SKU-NEGP", 1, -10.00m));
    }

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("ErrorCase")]
    public void AddItem_NullSku_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem(null!, 1, 5.00m));
    }

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("ErrorCase")]
    public void AddItem_EmptySku_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem(string.Empty, 1, 5.00m));
    }

    [TestMethod]
    [TestCategory("AddItem")]
    [TestCategory("EdgeCase")]
    public void AddItem_DuplicateSku_ThrowsNotImplementedException()
    {
        // Arrange — first call throws, so second is unreachable in stub;
        // this test documents the intent for when the method is implemented.
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem("SKU-DUP", 1, 5.00m));
    }

    // ───────────────────────────────────────────────
    // RemoveItem
    // ───────────────────────────────────────────────

    [TestMethod]
    [TestCategory("RemoveItem")]
    [TestCategory("HappyPath")]
    public void RemoveItem_ExistingSku_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    [TestCategory("RemoveItem")]
    [TestCategory("ErrorCase")]
    public void RemoveItem_NonExistentSku_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.RemoveItem("SKU-NONEXISTENT"));
    }

    [TestMethod]
    [TestCategory("RemoveItem")]
    [TestCategory("ErrorCase")]
    public void RemoveItem_NullSku_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.RemoveItem(null!));
    }

    [TestMethod]
    [TestCategory("RemoveItem")]
    [TestCategory("ErrorCase")]
    public void RemoveItem_EmptySku_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.RemoveItem(string.Empty));
    }

    // ───────────────────────────────────────────────
    // CalculateTotal
    // ───────────────────────────────────────────────

    [TestMethod]
    [TestCategory("CalculateTotal")]
    [TestCategory("HappyPath")]
    public void CalculateTotal_WhenCalled_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.CalculateTotal());
    }

    [TestMethod]
    [TestCategory("CalculateTotal")]
    [TestCategory("EdgeCase")]
    public void CalculateTotal_OnFreshCart_ThrowsNotImplementedException()
    {
        // Arrange — brand-new cart with no items added

        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.CalculateTotal());
    }

    // ───────────────────────────────────────────────
    // ApplyCoupon
    // ───────────────────────────────────────────────

    [TestMethod]
    [TestCategory("ApplyCoupon")]
    [TestCategory("HappyPath")]
    public void ApplyCoupon_ValidCode_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.ApplyCoupon("SAVE10"));
    }

    [TestMethod]
    [TestCategory("ApplyCoupon")]
    [TestCategory("HappyPath")]
    [DataRow("SUMMER25", DisplayName = "Seasonal coupon")]
    [DataRow("WELCOME", DisplayName = "Welcome coupon")]
    [DataRow("50OFF", DisplayName = "Numeric prefix coupon")]
    public void ApplyCoupon_VariousValidCodes_ThrowsNotImplementedException(string code)
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.ApplyCoupon(code));
    }

    [TestMethod]
    [TestCategory("ApplyCoupon")]
    [TestCategory("ErrorCase")]
    public void ApplyCoupon_NullCode_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.ApplyCoupon(null!));
    }

    [TestMethod]
    [TestCategory("ApplyCoupon")]
    [TestCategory("ErrorCase")]
    public void ApplyCoupon_EmptyCode_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.ApplyCoupon(string.Empty));
    }

    [TestMethod]
    [TestCategory("ApplyCoupon")]
    [TestCategory("EdgeCase")]
    public void ApplyCoupon_WhitespaceCode_ThrowsNotImplementedException()
    {
        // Act & Assert
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.ApplyCoupon("   "));
    }

    // ───────────────────────────────────────────────
    // Cross-method interaction scenarios
    // ───────────────────────────────────────────────

    [TestMethod]
    [TestCategory("Integration")]
    [TestCategory("HappyPath")]
    public void AddItemThenCalculateTotal_ThrowsNotImplementedException()
    {
        // Document intent: add item, then calculate total.
        // With stubs, AddItem throws first.
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem("SKU-INT", 2, 15.00m));
    }

    [TestMethod]
    [TestCategory("Integration")]
    [TestCategory("HappyPath")]
    public void AddItemThenRemoveItem_ThrowsNotImplementedException()
    {
        // Document intent: add then remove. Stub throws on add.
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.AddItem("SKU-REM", 1, 10.00m));
    }

    [TestMethod]
    [TestCategory("Integration")]
    [TestCategory("HappyPath")]
    public void ApplyCouponThenCalculateTotal_ThrowsNotImplementedException()
    {
        // Document intent: coupon then total. Stub throws on coupon.
        Assert.ThrowsException<NotImplementedException>(
            () => _cart.ApplyCoupon("DEAL20"));
    }
}

